    @Test void refundAndTransferReversalAreObservedWithoutFinancialWrites(){
        var f=new Fixture(false,1);f.reconcile();long initial=f.row().getRevision();f.allocations.getFirst().setReversalAmountMinor(100);
        f.client.data.get(f.client.key("/v1/charges/ch_audit",null)).put("amount_refunded",100);
        f.client.put("/v1/refunds?charge=ch_audit&limit=100",null,list(List.of(obj("id","re_audit","charge","ch_audit","payment_intent","pi_audit","amount",100,"currency","eur","status","succeeded","balance_transaction","txn_refund")),false));f.putBalance("txn_refund","re_audit",-100,0,null,"stripe_fee");
        var page=f.client.data.get(f.client.key("/v1/transfers?transfer_group=gratilo_"+f.tx.getId()+"&limit=100",null));StripePaymentAuditReader.map(((List<?>)page.get("data")).getFirst()).put("amount_reversed",100);
        f.client.put("/v1/transfers/tr_audit0/reversals?limit=100",null,list(List.of(obj("id","trr_audit","transfer","tr_audit0","amount",100,"currency","eur","balance_transaction","txn_reversal","destination_payment_refund","pyr_audit")),false));f.putBalance("txn_reversal","trr_audit",100,0,null,"stripe_fee");
        f.client.put("/v1/refunds/pyr_audit","acct_recipient0",obj("id","pyr_audit","charge","py_audit0","amount",100,"currency","eur","balance_transaction","txn_recipient_refund"));f.putBalance("txn_recipient_refund","pyr_audit",-100,0,"acct_recipient0","stripe_fee");
        f.reconcile();assertEquals("COMPLETE",f.row().getStatus());assertTrue(f.row().getRevision()>initial);assertEquals(100L,StripePaymentAuditReader.minor(f.report().get("refundedMinor")));assertEquals(330L,StripePaymentAuditReader.minor(f.report().get("transferredNetMinor")));assertEquals(30L,StripePaymentAuditReader.minor(f.report().get("platformResidualMinor")));long revision=f.row().getRevision();f.reconcile();assertEquals(revision,f.row().getRevision());assertEquals(430,f.allocations.getFirst().getAmountMinor());
    }
    @Test void provenDisputeFeesAreCapturedButPersonalEvidenceIsExcluded(){
        var f=new Fixture(false,1);f.client.put("/v1/disputes?charge=ch_audit&limit=100",null,list(List.of(obj("id","du_audit","livemode",false,"charge","ch_audit","payment_intent","pi_audit","amount",500,"currency","eur","status","lost","balance_transactions",List.of("txn_dispute"),"evidence",obj("customer_name","must never persist"))),false));f.putBalance("txn_dispute","du_audit",-500,1500,null,"stripe_fee");
        f.reconcile();assertEquals("COMPLETE",f.row().getStatus());assertEquals(1540,StripePaymentAuditReader.minor(f.report().get("platformBorneCostsMinor")));assertEquals(-1970,StripePaymentAuditReader.minor(f.report().get("platformResidualMinor")));assertFalse(f.row().getFinancialData().contains("must never persist"));
    }
