        f.client.data.get(f.client.key("/v1/charges/ch_audit","acct_direct")).put("amount_refunded",500);
        f.client.put("/v1/refunds?charge=ch_audit&limit=100","acct_direct",list(List.of(obj("id","re_direct","charge","ch_audit","amount",500,"currency","eur","status","succeeded","balance_transaction","txn_direct_refund")),false));f.putBalance("txn_direct_refund","re_direct",-500,0,"acct_direct","stripe_fee");
