    @Test void onlySignedWebhooksReachTheAuditBoundary()throws Exception{
        var f=new Fixture(false,1);f.reconcile();int count=f.store.history.size(),reads=f.client.reads;
        var legacyNoOp=new TransactionEntity();legacyNoOp.setId(f.tx.getId());legacyNoOp.setProvider("DEMO");
        // The signed audit must survive an early no-op return from the legacy business handler.
        var repository=(com.gratilo.payment.repository.TransactionRepository)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{com.gratilo.payment.repository.TransactionRepository.class},(p,m,a)->Optional.of(legacyNoOp));
        String secret="whsec_signaturefixture";var controller=new com.gratilo.payment.controller.StripeWebhookController(repository,secret,true,io.micronaut.json.JsonMapper.createDefault());
        var field=controller.getClass().getDeclaredField("paymentAuditor");field.setAccessible(true);field.set(controller,f.service);
        String body=StripePaymentAuditJson.write(f.webhook("evt_signed","charge.succeeded","ch_audit",null));
        assertEquals(io.micronaut.http.HttpStatus.UNAUTHORIZED,controller.receive(body,null).getStatus());assertEquals(count,f.store.history.size());
        long time=System.currentTimeMillis()/1000;var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(secret.getBytes(java.nio.charset.StandardCharsets.UTF_8),"HmacSHA256"));String signature="t="+time+",v1="+HexFormat.of().formatHex(mac.doFinal((time+"."+body).getBytes(java.nio.charset.StandardCharsets.UTF_8)));
        assertEquals(io.micronaut.http.HttpStatus.OK,controller.receive(body,signature).getStatus());assertEquals(io.micronaut.http.HttpStatus.OK,controller.receive(body,signature).getStatus());assertEquals(count+1,f.store.history.size());assertEquals(reads,f.client.reads);
    }
